import psycopg2; c=psycopg2.connect(host='127.0.0.1',port=5432,dbname='postgres',user='postgres',password='1234'); cur=c.cursor(); cur.execute('SELECT datname FROM pg_database'); print('databases->', cur.fetchall()); cur.execute('SELECT table_name FROM information_schema.tables WHERE table_schema=\'public\' ORDER BY table_name'); print('public_tables->', cur.fetchall()); cur.close(); c.close()
